package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import java.util.List;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StaticQuestionAnswerPolicyTest {
    private JSONObject graph(){return WorkflowModelCompiler.compile(StaticQuestionAnswerTestFixture.canvas(),(id,source,domain)->{throw new AssertionError("static profile cannot resolve model");}).execution();}
    private JSONObject pure(String id){return JSONObject.of("id",id,"data",JSONObject.of("nodeMeta",JSONObject.of("nodeType","text-joiner","aliasName",id),"inputs",new JSONArray(),"outputs",new JSONArray(),"nodeParam",JSONObject.of("template","")));}
    private void edge(JSONObject g,String source,String target){g.getJSONArray("edges").add(JSONObject.of("sourceNodeId",source,"targetNodeId",target));}
    private void chain(JSONObject g,int count){g.getJSONArray("edges").removeIf(o->"node-start::s".equals(((JSONObject)o).get("sourceNodeId")));String previous="node-start::s";for(int i=0;i<count;i++){String id="text-joiner::chain"+i;g.getJSONArray("nodes").add(pure(id));edge(g,previous,id);previous=id;}edge(g,previous,"question-answer::q");}
    private void paths(JSONObject g,int count){String start="node-start::s",current=start;g.getJSONArray("edges").removeIf(o->start.equals(((JSONObject)o).get("sourceNodeId")));String bits=Integer.toBinaryString(count).substring(1);for(int i=0;i<bits.length();i++){String l="text-joiner::p"+i+"L",r="text-joiner::p"+i+"R",m="text-joiner::p"+i+"M";for(String id:List.of(l,r,m))g.getJSONArray("nodes").add(pure(id));edge(g,current,l);edge(g,current,r);edge(g,l,m);edge(g,r,m);if(bits.charAt(i)=='1')edge(g,start,m);current=m;}edge(g,current,"question-answer::q");}
    @Test void maxPathLengthSixtyFourAcceptedAndSixtyFiveRefused(){var accepted=graph();chain(accepted,61);assertEquals(64,StaticQuestionAnswerPolicy.validate(accepted).maxPathLength());chainAddOne(accepted);assertEquals(413,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(accepted)));}
    private void chainAddOne(JSONObject g){g.getJSONArray("nodes").add(pure("text-joiner::last"));g.getJSONArray("edges").removeIf(o->"text-joiner::chain60".equals(((JSONObject)o).get("sourceNodeId")));edge(g,"text-joiner::chain60","text-joiner::last");edge(g,"text-joiner::last","question-answer::q");}
    @Test void totalPathsOneHundredTwentyEightAcceptedAndOneMoreRefusedWithoutEnumeration(){var a=graph();paths(a,128);assertEquals(128,StaticQuestionAnswerPolicy.validate(a).pathCount());var b=graph();paths(b,129);assertEquals(413,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(b)));}
    @Test void nodeCountOneHundredTwentyEightAcceptedAndOneMoreRefused(){var g=graph();g.getJSONArray("edges").removeIf(o->"node-start::s".equals(((JSONObject)o).get("sourceNodeId")));for(int i=0;i<125;i++){String id="text-joiner::wide"+i;g.getJSONArray("nodes").add(pure(id));edge(g,"node-start::s",id);edge(g,id,"question-answer::q");}assertEquals(128,g.getJSONArray("nodes").size());assertEquals(125,StaticQuestionAnswerPolicy.validate(g).pathCount());g.getJSONArray("nodes").add(pure("text-joiner::too-many"));assertEquals(413,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(g)));}
    @Test void duplicateEdgesDoNotMultiplyPathsAndDisconnectedPureNodeIsRejected(){var g=graph();edge(g,"node-start::s","question-answer::q");assertEquals(1,StaticQuestionAnswerPolicy.validate(g).pathCount());g.getJSONArray("nodes").add(pure("text-joiner::orphan"));assertEquals(400,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(g)));}
    @Test void ordinaryCyclesAndUndeclaredOrForwardReferencesAreRejected(){var cycle=graph();edge(cycle,"question-answer::q","node-start::s");assertEquals(400,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(cycle)));var ref=graph();var content=StaticQuestionAnswerTestFixture.data(ref,"question-answer::q").getJSONArray("inputs").getJSONObject(0).getJSONObject("schema").getJSONObject("value").getJSONObject("content");content.put("name","not-declared");assertEquals(400,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(ref)));content.put("nodeId","node-end::e");assertEquals(400,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(ref)));}
    @Test void externalSchemaAndUnknownGlobalReferenceRemainUnavailable(){var schema=graph();StaticQuestionAnswerTestFixture.data(schema,"node-start::s").getJSONArray("outputs").getJSONObject(0).getJSONObject("schema").put("$ref","https://schema.invalid/remote");assertEquals(503,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(schema)));var ref=graph();StaticQuestionAnswerTestFixture.data(ref,"question-answer::q").getJSONArray("inputs").getJSONObject(0).getJSONObject("schema").getJSONObject("value").getJSONObject("content").put("nodeId","node-variable::global");assertEquals(503,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(ref)));}
    @Test void allThreeQaImplicitIgnoreOutputsCannotOverwriteForeignDeclaredAddresses(){for(String address:List.of("query","content","id")){var g=graph();var d=StaticQuestionAnswerTestFixture.copy(StaticQuestionAnswerTestFixture.data(g,"question-answer::q"));d.put("outputs",new JSONArray());if(address.equals("id"))d.getJSONObject("nodeParam").put("answerType","option");g.getJSONArray("nodes").add(JSONObject.of("id","question-answer::q-x","data",d));StaticQuestionAnswerTestFixture.data(g,"question-answer::q").getJSONArray("outputs").add(JSONObject.of("name","x-"+address,"schema",JSONObject.of("type","string")));edge(g,"question-answer::q","question-answer::q-x");edge(g,"question-answer::q-x","node-end::e");assertEquals(400,StaticQuestionAnswerTestFixture.denied(()->StaticQuestionAnswerPolicy.validate(g)),address);}}
}
